custom_css:
/* ✦✦字体✦✦ */
@import url("data:text/css,@font-face{font-family:\"ZSFT-hd\";src:url(\"https://fontsapi.zeoseven.com/hd/medium.woff2\") format(\"woff2\");font-style:normal;font-weight:500;font-display:swap;} @font-face{font-family:\"ZSFT-hd\";src:url(\"https://fontsapi.zeoseven.com/hd/main.woff2\") format(\"woff2\");font-style:normal;font-weight:400;font-display:swap;}");
@import url("https://fontsapi.zeoseven.com/415/main/result.css");
@import url("data:text/css,%40font-face%7Bfont-family%3A%22ZSFT-hd%22%3Bsrc%3Aurl(%22https%3A%2F%2Ffontsapi.zeoseven.com%2Fhd%2Fmedium.woff2%22)%20format(%22woff2%22)%3Bfont-style%3Anormal%3Bfont-weight%3A500%3Bfont-display%3Aswap%3B%7D%40font-face%7Bfont-family%3A%22ZSFT-hd%22%3Bsrc%3Aurl(%22https%3A%2F%2Ffontsapi.zeoseven.com%2Fhd%2Fmain.woff2%22)%20format(%22woff2%22)%3Bfont-style%3Anormal%3Bfont-weight%3A400%3Bfont-display%3Aswap%3B%7D");
body {
  font-family: "WenYuan Serif SC VF";
  font-weight: normal;
}


/* ✦✦ㅇㅅㅇ✦✦ */
:root {
  --avatar-base-border-radius: 0px;
  --topBarBlockSize: 35px;
}


/* ✦✦ꔷ × ꔷ✦✦ */
* {
  /* border: none !important; */
  /* filter: none !important; */
  /* box-shadow: none !important; */
  /* text-shadow: none !important; */
  /* border-radius: 0px; */
}
::-webkit-scrollbar {
  display: none;
}
#clickSlidersTips,
span[name="samplerHelpButton"].note-link-span.fa-circle-question {
  display: none;
  color: transparent;
}
.last_mes .mesAvatarWrapper {
  padding-bottom: 0 !important;
}
.qr--head {
  display: flex;
  flex-direction: column;
}
#sheld,
#chat {
  border: none !important;
}
.avatar img {
  box-shadow: none;
  border: none;
}


/* ⌯'ㅅ'⌯ */
#avatar_div_div {
  filter: none;
  margin: 5px 0 132px;
  padding: 0 !important;
  display: flex;
  justify-content: center;
  position: relative;
  background: url("https://img.heliar.top/file/1772429026180_1772428972781.png") center center / cover no-repeat;
}
#avatar_div_div img {
  border-radius: 50px !important;
  height: 50px;
  position: relative;
  bottom: -60px;
}
#avatar_div_div::before {
  content: "“A transparent gradient.”";
  font-family: "ZSFT-hd";
  white-space: nowrap;
  color: gray;
  position: absolute;
  left: 6px;
  top: 108px;
  font-size: 28px;
  z-index: 45;
}
#avatar_div_div::after {
  content: "▪️But the most profound change, my darling, would be in your eyes.\AThey already hold the universe for me.";
  white-space: pre;
  text-align: center;
  color: black;
  position: absolute;
  top: 152px;
  font-size: 8px;
}
.form_create_bottom_buttons_block {
  display: flex;
  justify-content: center;
}
#avatar_div {
  display: flex;
  flex-direction: column;
  gap: 0;
  padding: 0px;
}



/* 正则 */
.regex_script_name {
  white-space: normal;
  word-break: break-all;
}
.regex-script-label:not(:has(input[type='checkbox']:checked)) {
  background-color: whitesmoke;
  border-radius: 0px;
}
.regex-script-label {
  max-width: 85%;
}
.drag-handle.menu-handle {
  position: relative;
  color: transparent;
}
.drag-handle.menu-handle::before {
  position: absolute;
  content: "❥";
  color: black;
}
#global_scripts_block #saved_regex_scripts {
  max-height: 600px;
  overflow-y: auto;
}


/* ✦✦文本✦✦ */
pre code:not(#qr--modal-messageHolder pre code) {
  color: black !important;
  background-color: white !important;
  border-radius: 0px;
  -webkit-box-decoration-break: clone;
  box-shadow:
    1px 1PX 2px 0 rgba(0,0,0,0.25);
}
:not(pre) > code {
  color: white;
  background-color: black;
  border-radius: 0px;
  padding: 0px 0px;
}
/* 分割线文字 */
hr {
  position: relative;
  display: flex;
  align-items: center;
  justify-content: center;
  width: 100%;
  min-width: 100%;
  max-width: 100%;
  height: auto !important;
  min-height: 28px !important;
  margin: 0px !important;
  padding: 0px !important;
  text-align: center;
  white-space: nowrap;
  line-height: 1 !important;
  opacity: 1 !important;
  background-image: none !important;
  border: none !important;
}
hr::before {
  content: "▪𝗛𝗮𝗽𝗽𝗶𝗹𝘆 𝗘𝘃𝗲𝗿 𝗔𝗳𝘁𝗲𝗿▪";
  font-size: 14px;
  color: black; 
}
.options-content hr {
  font-size: 8px !important;
}
/* 引用 */
blockquote {
  background: white !important;
  border-radius: 0px;
  margin: 7px 0 14px !important;
  padding: 0px 14px;
  border-left: 3px solid black !important;
  color: black;
  font-style: italic;
}
/* 其他 */
.no-blur q {
  opacity: 1 !important;
  border-radius: 0px;
  box-decoration-break: clone;
}
.mes strong {
  text-shadow: none !important;
  color: var(--SmartThemeBodyColor);
}


/* ✦✦顶栏✦✦ */
#top-bar {
  width: 10px;
  box-shadow: none;
}
#top-settings-holder {
  background-color: #07080C;
  width: 100dvw;
  margin: 0px auto;
  justify-content: center;
  position: relative;
}
#top-settings-holder .drawer-icon {
  position: relative;
  width: 100%;
  font-size: 18px;
  color: transparent;
  background: linear-gradient(
    135deg,
    white 50%,
    transparent 100%
  );
  -webkit-background-clip: text !important;
  border-radius: 0px;
}
#top-settings-holder .drawer-icon.closedIcon {
  opacity: 1;
}
#top-settings-holder .drawer-icon.openIcon {
  opacity: 1;
}


/* ✦✦chat✦✦ */
#show_more_messages {
  all: unset;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  height: 30px;
  margin: 10px auto 10px;
  padding: 2px 10px;
  position: relative;
  border-radius: 25px;
  font-size: 0;
  border: 1px solid gray;
  background-color: white;
}
#show_more_messages::after {
  content: "•  Last in the rain.";
  font-size: 12px;
  font-weight: bold;
  pointer-events: none;
  white-space: nowrap;
}

.mes .mes_block {
  overflow: visible;
  margin: 0px 0px;
  padding: 0px 0px;
  border-radius: 0px;
  background-color: transparent;
  width: 100%;
  position: relative;
}
.mes_block::after {
  content: "罪与爱同歌";
  position: absolute;
  bottom: -65px;
  left: 36%;
  line-height: 1;
  white-space: nowrap;
  font-size: 1.5em;
  color: white;
  z-index: 45;
}
.mes[is_user="true"] .mes_block::after {
  content: "无尽夏";
  bottom: -58px;
  left: 42%;
}
.mes_block::before {
  content: "The world is already murky, sin and love sing together.";
  position: absolute;
  bottom: -95px;
  left: 5%;
  line-height: 1.6;
  white-space: normal;
  text-align: center;
  font-size: 0.8em;
  color: white;
  width: 90%;
  overflow-x: hidden;
  z-index: 15 !important;
}
.mes[is_user="true"] .mes_block::before {
  content: "The sky is a canvas, painted with the most glorious hues at sunrise and sunset.";
  bottom: -100px;
  left: 5%;
}
.mes_text {
  padding: 15px 0 0;
  margin: 0;
  border-top: 0.8px solid black;
  position: relative;
}
.mes_text p:first-child {
  margin-top: -0.3em;
}
.mes_text p:last-child {
  margin-bottom: -0.3em;
}
.mes_text p {
  padding: 0;
  text-align: justify;
  text-justify: inter-character;
  overflow-wrap: break-word;
  line-break: anywhere;
  word-break: normal;
  letter-spacing: 0.05em;
  line-height: 1.6;
}

#chat .mes {
  position: relative;
  padding: 15px 0px;
  margin: 334px auto 165px;
  border-radius: 0px;
  align-items: center;
  flex-direction: column;
  width: calc(100dvw - 30px);
  border-top: 0.8px solid black;
  border-bottom: 0.8px solid black;
  background-color: transparent;
  z-index: -1 !important;
}
.mes::before {
  content: "";
  width: calc(100% + 15px);
  height: 80px;
  position: absolute;
  bottom: -95px;
  background-color: rgba(0,0,0,0.25);
  backdrop-filter: blur(5px);
}
.mes::after {
  content: "";
  width: calc(100% + 15px);
  height: 80px;
  position: absolute;
  bottom: -95px;
  background: url("https://img.heliar.top/file/1772426664939_1772426654216.png") center center / cover no-repeat;
  z-index: -22;
}
.mes[is_user="true"]::after {
  background-image: url("https://img.heliar.top/file/1772361033709_1772361002485.png");
}

.last_mes {
  margin-bottom: 240px !important;
}

.mes.smallSysMes {
  margin: 20px auto 180px !important;
}

.mesAvatarWrapper {
  position: absolute;
  top: -195px;
  left: 50%;
  transform: translateX(-50%);
  height: 180px;
  width: 100%;
  border-radius: 0px;
  background-color: transparent;
  margin: 0px auto;
}
.mesAvatarWrapper::before {
  content: "CUSTOMIZE";
  position: absolute;
  top: -82px;
  left: -54px;
  font-family: none;
  white-space: nowrap;
  font-weight: 800;
  font-size: 6em;
  color: black;
  opacity: 0.07;
}
.mes .avatar {
  width: 100%;
  height: 180px;
  border-radius: 0px;
  margin: 0px;
  position: relative;
  left: 0px;
  top: 0px;
}
.mes .avatar img {
  border-radius: 0px;
  width: 100%;
  height: 100%;
}
.mes .avatar::before {
  content: "誰も知らない私";
  pointer-events: none;
  position: absolute;
  top: -55px;
  font-size: 30px;
  width: 100%; 
  white-space: nowrap;
  line-height: 1;
  padding: 5px 0 5px 8px;
  border-left: 3px solid black;
}
.mes[is_user="true"] .avatar::before {
  content: "幸せが続きますように";
}
.mes .avatar::after {
  content: "● SWEET DREAMS";
  pointer-events: none;
  font-family: none;
  position: absolute;
  left: 0;
  top: -140px;
  letter-spacing: 4px;
  font-size: 12px;
  width: 100%; 
  white-space: nowrap;
  line-height: 1;
  padding: 5px 0px;
  border-bottom: 0.8px solid black;
}
.mes[is_user="true"] .avatar::after {
  content: "● Heart Burning";
}

.mesIDDisplay,
.mes_timer,
.mes .tokenCounterDisplay {
  position: absolute;
  opacity: 1 !important;
  font-size: 10px !important;
  font-weight: 400 !important;
  line-height: 1;
  padding: 5px 7px;
  background-color: black;
  color: white;
}
.mesIDDisplay {
  left: 0px;
  top: -95px;
}
.mesIDDisplay::before {
  content: "VOL. ";
}
.mes .tokenCounterDisplay {
  left: 100px;
  top: -95px;
}
.mes_timer { 
  left: 200px;
  top: -95px;
}
.mes .tokenCounterDisplay:empty,
.mes_timer:empty {
  display: none;
}

.mes .ch_name {
  margin: 0 0 100px 0;
  padding: 0;
  max-width: 100%;
  line-height: 1;
  position: relative;
  top: 0px;
  left: 0;
  overflow: visible;
}
.mes .ch_name .flex-container.flex1 {
  position: relative;
  top: 0px;
  width: 100%;
  line-height: 1;
  padding: 6px 0 5px 8px;
  border-left: 1.5px solid rgba(0,0,0,0.25);
}
.mes .name_text {
  max-width: calc(100dvw - 45px);
  overflow-x: hidden !important;
  font-size: 30px;
  white-space: nowrap;
  color: rgba(0,0,0,0.25);
}
.mes .name_text::before {
  position: relative;
  top: -2px;
  content: "PUPPY：";
  font-size: 25px;
}
.mes[is_user="true"] .name_text::before {
  content: "MASTER：";
}
.mes .name_text::after {
  content: "Ambition.";
  position: absolute;
  left: 22px;
  bottom: -24px;
  text-align: center;
  white-space: nowrap;
  font-size: 100px;
  opacity: 0.08;
}
.mes .timestamp {
  position: absolute;
  overflow-x: hidden;
  width: 100%;
  bottom: -50px;
  left: -1.5px;
  font-size: 12px;
  font-family: none;
  font-weight: 800;
  white-space: nowrap;
  background-color: black;
  color: white;
  padding: 10px 15px 10px 5px;
  opacity: 1;
}
.mes .timestamp::before {
  content: "▪ Writing   ";
  white-space: pre;
}
.mes_buttons,
.mes_button,
.mes_edit_buttons {
  filter: none !important;
  opacity: 1 !important;
}
.mes .mes_buttons {
  position: absolute;
  bottom: -84px;
  left: -3px;
}
.mes_button.mes_edit,
.mes_button.extraMesButtonsHint {
  position: relative;
  white-space: nowrap;
  font-size: 13px;
  font-family: "WenYuan Serif SC VF";
}
.mes_button.extraMesButtonsHint {
  margin-right: 25px;
}
.mes_button.mes_edit::before {
  content: "ECHO：";
}
.mes_button.mes_edit::after {
  content: "Chamber";
  background-color: rgba(0,0,0,0.08);
  padding: 3px 9px 2px;
}
.mes_button.extraMesButtonsHint::before {
  content: "LIGHT："
}
.mes_button.extraMesButtonsHint::after {
  content: "Shadow";
  background-color: rgba(0,0,0,0.08);
  padding: 3px 9px 2px;
}
.mes_edit_buttons {
  position: relative;
  top: 75px;
}

/* 思维链 */
.mes_reasoning_summary {
  margin: 0 !important;
}
.mes_reasoning_header_block {
  position: relative;
  left: 0;
  top: 0px;
}
.mes_reasoning_details {
  min-width: 100% !important;
  max-width: 100%;
}
.mes_reasoning_header {
  max-height: 2em;
  min-height: 2em;
  height: 2em;
  padding: 0px 6px;
  margin: 0px 0px 15px;
  background-color: transparent;
  color: transparent;
  border-radius: 0px;
  border: none;
  box-shadow: none;
  font-size: 15px;
  font-family: "WenYuan Serif SC VF";
  line-height: 1;
  white-space: nowrap;
  display: flex;
  align-items: center;
  justify-content: center;
  width: 100%;
  position: relative;
}
.mes_reasoning_header::before {
  content: "CELEBRATE▪REFRESH▪RENEW";
  position: absolute;
  color: black;
}
.mes_reasoning_details[open] .mes_reasoning_header {
  background-color: black;
  color: transparent;
}
.mes_reasoning_details[open] .mes_reasoning_header::before {
  color: white;
}
.mes_reasoning_arrow {
  display: none;
}
.mes_reasoning,
.mes .reasoning_edit_textarea {
  text-align: justify;
  max-height: 240px;
  margin: 0px 0px 15px;
  padding: 7px 10px;
  border: none;
}

.swipeRightBlock {
  bottom: -130px;
  width: 100%;
}
.swipeRightBlock::after {
  content: "“Heart Burning.”";
  position: absolute;
  left: 12px;
  bottom: -15px;
  text-align: center;
  white-space: nowrap;
  font-size: 35px;
  font-family: "ZSFT-hd";
  opacity: 0.08;
}
.swipe_left {
  position: absolute;
  left: 6px;
  bottom: -130px;
  opacity: 1 !important;
  border-radius: 0px;
}
.swipe_left::before {
  font-family: "WenYuan Serif SC VF";
  content: "▪I";
}
.swipe_right {
  position: absolute;
  right: 10px;
  bottom: 0px;
  opacity: 1 !important;
  border-radius: 0px;
}
.swipe_right::before {
  font-family: "WenYuan Serif SC VF";
  content: "A▪";
}
.swipes-counter,
body.swipeAllMessages .mes:not(.last_mes) .swipes-counter {
  position: relative;
  bottom: -2px;
  opacity: 1 !important;
  font-family: "WenYuan Serif SC VF";
}
.swipes-counter::before {
  content: "——  Heart  ";
  white-space: pre;
}
.swipes-counter::after {
  content: "  Burning  ——";
  white-space: pre;
}
.mes:not(.last_mes) .swipeRightBlock {
  display: none;
}


/* ✦✦底栏✦✦ */
#form_sheld {
  position: absolute;
  bottom: 10px;
}
#sheld #send_form {
  background-color: black !important;
  box-shadow:
    0 0px 3px 0 rgba(0,0,0,0.25);
  border-radius: 0px;
  padding: 12px 4px !important;
  margin: 0px auto;
  width: 94%;
  position: relative;
}
#sheld #send_textarea {
  border: none !important;
  clip-path: none !important;
  transition: none !important;
  resize: none;
  width: 100%;
  max-height: 100px;
  min-height: 0px;
  padding: 6px 4px;
  margin: 0px;
  position: relative;
  border-radius: 0px !important;
  background: white !important;
}
#nonQRFormItems {
  position: relative;
  padding: 0px !important;
}
#send_textarea::placeholder {
  opacity: 0;
}
#nonQRFormItems::before {
  pointer-events: none;
  transition: opacity .15s ease;
  content: "𝐈 𝐖𝐀𝐍𝐓 𝐘𝐎𝐔 𝐁𝐘 𝐌𝐘 𝐒𝐈𝐃𝐄.";
  font-size: 13.5px;
  position: absolute;
  top: 6px;
  left: 90px;
  color: rgba(0,0,0,1);
  z-index: 45;
}
#nonQRFormItems:has(#send_textarea:focus)::before {
  content: "User was typing......";
  top: 8px;
}
#nonQRFormItems:has(#send_textarea[placeholder^="未连接到"])::before {
  content: "未连接到api𖦹𖦹 .ᐟ.ᐟ";
}
#nonQRFormItems:has(#send_textarea:not(:placeholder-shown))::before {
  opacity: 0;
}
/* 展开菜单 */
#extensionsMenu,
#options {
  border: none;
  border-radius: 0;
  background-color: white;
  box-shadow: 0 0 5px 0 rgba(0,0,0,0.25);
  margin-bottom: 5px !important;
}
.options-content {
  border: none;
}
#nonQRFormItems [class*="fa-"] {
  opacity: 1 !important;
  filter: none !important;
  color: transparent;
  background: linear-gradient(
    135deg,
    white 50%,
    transparent 100%
  );
  -webkit-background-clip: text !important;
  border-radius: 0px;
  position: relative;
  padding: 0;
  width: var(--bottomFormBlockSize);
  height: var(--bottomFormBlockSize);
  font-size: 18px;
}
#mes_stop {
  opacity: 1 !important;
  filter: none !important;
}
.fa-solid.fa-circle-stop {
  display: flex;
  justify-content: center;
  align-items: center;
}
#qr--bar {
  pointer-events: auto;
  opacity: 1 !important;
  max-height: 50px;
  display: none !important;
}
#send_form:focus-within #qr--bar {
  display: block !important;
}
#send_form:has(#send_textarea:focus) {
  padding-top: 0 !important;
}


/* ✦✦其他✦✦ */
.drawer-content {
  /* 只减去顶部高度 */
  height: calc(100dvh - var(--topBarBlockSize)) !important;
  min-height: calc(100dvh - var(--topBarBlockSize)) !important;
  max-height: calc(100dvh - var(--topBarBlockSize)) !important;
  border-radius: 0px !important;
  padding: 5px 10px 0px !important;
  border: none !important;
  background-color: white;
}
#wi-holder {
  margin: 0;
}
.scrollableInner {
  padding: 0 0em;
}
#left-nav-panel .scrollableInner {
  min-height: 100%;
}
#form_create,
.persona_management_left_column,
#world_popup {
  padding: 2px;
}


/* 欢迎面板 */
.welcomePanel {
  background: transparent !important;
  border: none !important;
}
.welcomePanel .recentChatList .recentChat {
  margin: 0px -5px 3px;
  padding: 5px !important;
  border: none !important;
  border-radius: 0px !important;
  position: relative;
}
.recentChatList .recentChat .recentChatInfo {
  padding: 0px 4px 4px !important;
  margin: 0!important;
}
/* 去掉‘|’ */
.welcomeRecent .recentChatList .recentChat .chatStats .counterBlock::after {
  content: none;
}
.welcomePanel .welcomeShortcuts .welcomeShortcutsSeparator {
  color: transparent;
}


/* 文本框、搜索、弹窗内*/
textarea:not(#qr--modal-message):not(#vectors_force_chunk_delimiter),
textarea.text_pole:not(#vectors_force_chunk_delimiter) {
  box-shadow:
    0 0 2px 0 rgba(0,0,0,0.25);
  opacity: 1 !important;
  border-radius: 5px;
  background-color: white !important;
  border: none;
  resize: none;
}
input.text_pole,
#vectors_force_chunk_delimiter {
  border-radius: 0px;
  background: white !important;
  border: 1px solid rgba(0,0,0,0.25) !important;
  box-shadow: none !important;
}
textarea:focus,
textarea.text_pole:focus,
input.text_pole:focus {
  outline: none;
}
#qr--modal-messageHolder {
  background: whitesmoke !important;
  margin: 20px 0 0!important;
}


/* 对话弹窗 */
.popup:not(:has(#load-spinner)),
#character_popup,
#select_chat_popup,
#ti_usage_guide_dialog,
#completion_prompt_manager_popup,
#ti_usage_guide_dialog {
  border: none !important;
  border-radius: 5px;
  background-color: white !important;
}
.popup-body {
  padding-bottom: 7px !important;
}
.popup-content {
  padding: 6px 6px!important;
}


/* 提示框 */
body #toast-container {
  position: fixed;
  top: 0;
  left: 0;
  width: 100%;
  text-align: center;
  pointer-events: none;
}
body #toast-container>div {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  width: fit-content !important;
  max-width: 90dvw;
  padding: 10px 10px 10px 14px;
  margin: 10px 0 10px;
  pointer-events: auto;
  text-align: left;
  vertical-align: middle;
  word-break: break-all;
}
/* 正常 */
body #toast-container .toast-success {
  overflow: visible;
  color: black;
  position: relative;
  border-radius: 5px;
  background: white !important;
  box-shadow:
    0 0 5px 0 rgba(0,0,0,0.25);
}
/* 报错 */
body #toast-container .toast-error {
  overflow: visible;
  color: #9f2441;
  border-radius: 0px;
  background: #fff5f5 !important;
  box-shadow:
    0 0 5px 0 rgba(255,180,180,0.4);
}
/* 警告 */
body #toast-container .toast-warning {
  overflow: visible;
  color: #8b6f1e;
  border-radius: 5px;
  background: #ffffeb !important;
  box-shadow:
    0 0 5px 0 rgba(255,210,130,0.25);
}
/* 信息 */
body #toast-container .toast-info {
  overflow: visible;
  color: #1d6f8c;
  border-radius: 0px;
  background: #e6f7ff !important;
  box-shadow:
    0 0 5px 0 rgba(130,200,255,0.4);
}


/* 复选框 */
.qr--item {
  display: flex !important;
  align-items: center !important;
}
div.pointer-events-auto.mr-0\.5.flex.shrink-0.items-center.rounded-sm *,
label:has(input[type="checkbox"]) *,
.checkbox_label *,
.checkbox.flex-containe *,
.extension_toggle * {
  line-height: 1 !important;
