}
div.pointer-events-auto.flex.shrink-0.items-center.rounded-sm,
label:has(input[type="checkbox"]),
.checkbox_label,
.checkbox.flex-containe,
.extension_toggle {
  filter: none !important;
  padding: 0 !important;
  margin: 6px 2px !important;
  gap: 8px !important;
  display: flex !important;
  align-items: center !important;
}
input[type="checkbox"]::before {
  content: none !important;
}
input[type="checkbox"] {
  transform: translateY(0) !important;
  outline: none !important;
  filter: none !important;
  opacity: 1 !important;
  background: transparent;
  color: black !important;
  box-shadow: none;
  border: 0.8px solid black;
  border-radius: 25px;
  line-height: 1;
  width: 13px;
  height: 13px;
  overflow: visible;
  position: relative;
}
input[type="checkbox"]:checked {
  border: none;
}
input[type="checkbox"]:checked::after {
  content: "✦";
  line-height: 1;
  font-size: 16px;
  position: absolute;
  top: -3px;
}


