/* 滑杆 */
/* 禁用滤镜 */
.neo-range-slider:disabled,
input[type="range"]:disabled,
.alignitemscenter:has(.neo-range-slider:disabled) .neo-range-input,
.range-block:has(input[type="range"]:disabled) .range-block-counter input {
  filter: brightness(85%) !important;
}
/* 输入框 */
.neo-range-input,
.range-block-counter input {
  border: none;
  background-color: black;
  color: white;
  line-height: 2;
  border-radius: 12px 12px 0px 0px;
  box-shadow: 
    inset 0px -3px 0 0px black,
    inset 0px -5px 0 0px white;
  padding: 0px;
  margin-top: 5px;
  margin-bottom: 2.5px;
}
.doubleRangeInputContainer {
  overflow: visible !important;
}
/* 滑块1 */
/* 隐藏滑块原样式 */
.neo-range-slider,
input[type="range"] {
  filter: none !important;
  background: transparent !important;
  box-shadow: none !important;
}
/* 按钮 */
.neo-range-slider::-webkit-slider-thumb,
input[type="range"]::-webkit-slider-thumb {
  width: 13px;
  height: 13px;
  border: none; 
  background-color: white;
  border: 1.5px solid black;
  margin-top: -5px;
}
/* 轨道 */
.neo-range-slider::-webkit-slider-runnable-track,
input[type="range"]::-webkit-slider-runnable-track {
  height: 2.5px;
  background-color: black;
  border-radius: 0px;
}
/* 2 */
/* 按钮 */
#smooth_streaming_speed_control input[type="range"]::-webkit-slider-thumb,
div.range-block-range input[type="range"]::-webkit-slider-thumb {
  width: 15px;
  height: 15px;
  border: 1.25px solid white; 
  border-radius: 0px;
  background-color: rgba(0,0,0,0.85);
  box-shadow: 
    0.5px 0.5px 2px 0 rgba(0,0,0,0.25);
  margin-top: -2px;
}
/* 轨道 */
#smooth_streaming_speed_control input[type="range"]::-webkit-slider-runnable-track,
.range-block-range input[type="range"]::-webkit-slider-runnable-track {
  height: 12px;
  background-color: white;
  box-shadow: 
    inset 1px 1px 2px 0 rgba(0,0,0,0.08),
    1px 1px 2px 0 rgba(0,0,0,0.25);
  border-radius: 0px;
}
.range-block-range input[type="range"]::-webkit-slider-runnable-track {
  margin-top: 20px;
}
#smooth_streaming_speed_control .slider_hint {
  margin: 15px 0 0 !important;
}


