/* 完全替换预加载器 */
#preloader {
  background: url("https://img.heliar.top/file/1770985830751_1770985806853.png") center center / cover no-repeat;
}
.popup[open]:has(#load-spinner)::backdrop {
  background: none;
}
#load-spinner {
  transition: none;
  color: transparent;
  background: url("https://files.catbox.moe/g7qrlv.png") center center / contain no-repeat;
  filter: drop-shadow(0px 0px 5px rgba(255, 255, 255, 0.95));
  animation: floatPulse 2.5s ease-in-out infinite;
}
@keyframes floatPulse {
  0%, 100% {
    transform: translateY(0) scale(1);
    opacity: 0.9;
  }
  25% {
    transform: translateY(-12px) scale(1.05);
    opacity: 1;
  }
  50% {
    transform: translateY(5px) scale(0.95);
    opacity: 0.85;
  }
  75% {
    transform: translateY(-8px) scale(1.03);
    opacity: 0.95;
  }
}
